{
  "resourceType": "Bundle",
  "type": "collection",
  "entry": [
    {
      "fullUrl": "https://example.org/fhir/Patient/patient-1",
      "resource": {
        "resourceType": "Patient",
        "id": "patient-1",
        "gender": "female"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-1",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-1",
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "verificationStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "provisional"
            }
          ]
        },
        "code": {
          "text": "Known iron deficiency with likely iron-deficiency anaemia"
        },
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-2",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-2",
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "code": {
          "text": "Heavy menstrual bleeding"
        },
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Haemoglobin"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 104,
          "unit": "g/L"
        },
        "note": [
          {
            "text": "Old EMR result, approximately 4–5 months before the consultation."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Mean corpuscular volume (MCV)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 72,
          "unit": "fL"
        },
        "note": [
          {
            "text": "Old EMR result, approximately 4–5 months before the consultation."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Ferritin"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 7,
          "unit": "mcg/L"
        },
        "note": [
          {
            "text": "Old EMR result, approximately 4–5 months before the consultation."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Other old laboratory results"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "WCC, platelets, U&E and LFTs were reported as normal approximately 4–5 months before the consultation."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Bilateral exertional leg pain"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Crampy, heavy ache in both calves, possibly extending to the thighs, right greater than left. Occurs after a few minutes of walking, for example walking from the train to school, and eases after a few minutes of rest. No nocturnal or rest pain reported. Onset unclear; patient alternates between saying last week and a few months ago."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Fatigue"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports marked fatigue, feeling wiped out by mid-afternoon and knackered by 3 pm."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Exertional shortness of breath and reduced exercise tolerance"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports increased shortness of breath on stairs and reduced exercise tolerance."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Other reported symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Occasional headaches and mild pagophagia, described as craving ice a bit."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Menstrual history"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Heavy bleeding for the first 2–3 days, changing tampons approximately hourly. Cycle every 28–32 days, lasting 6–7 days. Denies intermenstrual bleeding and postcoital bleeding."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Pregnancy status as reported"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies current pregnancy; last menstrual period approximately 3 weeks before the consultation."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Pertinent reported negatives"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies chest pain, palpitations, presyncope, syncope, back pain, bowel or bladder changes, paraesthesia, and weakness."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Telephone consultation observations"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Alert and coherent, speaking in full sentences. No audible shortness of breath, cough, or wheeze. Legs could not be visually inspected; no vital signs were available."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "stopped",
        "medicationCodeableConcept": {
          "text": "Oral iron tablets (brand and dose unknown)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "note": [
          {
            "text": "Previously used and stopped because of gastrointestinal upset, described as making the patient's tummy feel weird."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-2",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-2",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Nurofen"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "Occasional use; dose and directions not stated."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Ferro-grad C 325 mg (105 mg elemental iron plus vitamin C)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "Take one tablet by mouth each morning. Take away from tea, coffee, and dairy where possible; may take with a small amount of food if gastrointestinal upset occurs. If daily dosing is poorly tolerated, may trial alternate-day dosing and inform the clinician. Continue at least 3 months after haemoglobin normalises, then for a further 3 months to replenish stores; total approximately 3–6 months depending on results.",
            "route": {
              "text": "oral"
            },
            "timing": {
              "repeat": {
                "frequency": 1,
                "period": 1,
                "periodUnit": "d",
                "when": [
                  "MORN"
                ]
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 1,
                  "unit": "tablet"
                }
              }
            ]
          }
        ]
      }
    }
  ]
}
